let viewRevision = 0;
let toastRevision = 0;

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const money = (value, currency = 'DOP') => new Intl.NumberFormat('es-DO', { style: 'currency', currency, maximumFractionDigits: 2 }).format(Number(value || 0));
function accountsForProfile() { return state.profile === 'Personal' ? DEMO.personalAccounts : DEMO.accounts; }
function toast(message) { state.toast = message; const revision = ++toastRevision; render(); setTimeout(() => { if (revision !== toastRevision) return; state.toast = ''; root.querySelector('.toast')?.remove(); }, 2800); }
function setPage(page, wait = true) {
  const revision = ++viewRevision;
  state.alert = ''; state.notifications = false;
  if (wait) { state.loading = true; render(); setTimeout(() => { if (revision !== viewRevision) return; state.page = page; state.loading = false; render(); }, 420); }
  else { state.page = page; render(); }
}
function requireAuth() { if (!state.authenticated) { state.page = 'login'; render(); return false; } return true; }
function input(label, key, value = '', type = 'text', attrs = '') { return `<div class="field"><label for="${esc(key)}">${esc(label)}</label><input id="${esc(key)}" name="${esc(key)}" type="${type}" value="${esc(value)}" ${attrs}></div>`; }
function select(label, key, choices, value = '') { return `<div class="field"><label for="${esc(key)}">${esc(label)}</label><select id="${esc(key)}" name="${esc(key)}">${choices.map(([v,t]) => `<option value="${esc(v)}" ${v === value ? 'selected' : ''}>${esc(t)}</option>`).join('')}</select></div>`; }
function spinner(label = 'Cargando información segura…') { return `<div class="loading-screen" aria-label="Estado de carga"><div class="loading-box"><span class="spinner large" aria-hidden="true"></span><strong>Estado de carga</strong><span>${esc(label)}</span><span role="status">Espera mientras el portal actualiza los datos.</span></div></div>`; }
function shell(content, title = 'Resumen') {
  if (!requireAuth()) return '';
  const nav = state.profile === 'Personal'
    ? [['dashboard','▦','Resumen'], ['accounts','◫','Mis cuentas'], ['transfer','⇄','Transferencias'], ['payments','▣','Pagos'], ['statements','▤','Movimientos'], ['personal-loan','⌂','Solicitar préstamo'], ['audit','◷','Seguridad']]
    : [
    ['dashboard','▦','Resumen'], ['accounts','◫','Cuentas'], ['transfer','⇄','Transferencias'], ['beneficiaries','♧','Beneficiarios'], ['payments','▣','Pagos'], ['statements','▤','Estados de cuenta'], ['payroll','▥','Pagos masivos'], ['admin','⚙','Administración'], ['audit','◷','Auditoría'],
  ];
  return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">N</div><div><strong>Northstar</strong><small>Portal ${state.profile.toLowerCase()}</small></div></div><div class="nav-group"><div class="nav-caption">${state.profile === 'Personal' ? 'Mis productos' : 'Operaciones'}</div>${nav.slice(0,state.profile === 'Personal' ? nav.length : 7).map(([id,icon,label]) => `<button class="nav-link" data-page="${id}" aria-current="${state.page === id ? 'page' : 'false'}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}</div>${state.profile !== 'Personal' ? `<div class="nav-group"><div class="nav-caption">Administración y control</div>${nav.slice(7).map(([id,icon,label]) => `<button class="nav-link" data-page="${id}" aria-current="${state.page === id ? 'page' : 'false'}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}</div>` : ''}<div class="sidebar-bottom"><strong>Espacio de pruebas</strong><br>Datos ficticios · sin conexión bancaria<br>Entorno: REGRESSION-LAB</div></aside><main class="main"><header class="topbar"><div class="crumb">Northstar <span aria-hidden="true">/</span> ${esc(title)}</div><div class="top-actions"><button class="icon-button" data-action="search" aria-label="Buscar en el portal">⌕</button><button class="icon-button" data-action="notifications" aria-label="Notificaciones">♧<span class="badge">3</span></button><button class="user-pill" data-action="user-menu"><span class="avatar">QD</span><span><strong>QA Demo</strong><br><small>Cliente ${state.profile.toLowerCase()}</small></span>⌄</button></div>${state.notifications ? `<div class="notification-pop"><strong>Centro de notificaciones</strong><p class="activity-meta">3 eventos requieren revisión.</p><div class="activity"><span class="activity-name">Transferencia en proceso</span><span class="tag amber">Pendiente</span></div><div class="activity"><span class="activity-name">Nuevo estado de cuenta</span><span class="activity-meta">Hoy</span></div></div>` : ''}</header><section class="content">${state.loading ? spinner() : content}</section></main>${state.toast ? `<div class="toast" role="status">${esc(state.toast)}</div>` : ''}${state.beneficiaryDialog ? beneficiaryDialog() : ''}</div>`;
}
function pageHead(kicker, title, subtitle, actions = '') { return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="head-actions">${actions}</div></div>`; }
function dashboard() {
  if (state.profile === 'Personal') return personalDashboard();
  const total = accountsForProfile().reduce((sum, account) => sum + account.balance, 0);
  const content = `${pageHead('Mi empresa · vista general','Resumen de productos','Consulta saldos, actividad reciente y tareas pendientes.', '<button class="button secondary" data-page="statements">Ver estados de cuenta</button><button class="button" data-page="transfer">Nueva transferencia</button>')}<div class="grid stats"><article class="card"><div class="stat"><div><div class="stat-label">Balance total</div><div class="stat-value">${money(total)}</div><div class="stat-note">+2.4% este mes</div></div><div class="stat-icon">↗</div></div></article><article class="card"><div class="stat"><div><div class="stat-label">Cuentas activas</div><div class="stat-value">03</div><div class="stat-note">Todas disponibles</div></div><div class="stat-icon">▤</div></div></article><article class="card"><div class="stat"><div><div class="stat-label">Pendientes de aprobación</div><div class="stat-value">02</div><div class="stat-note">Requieren revisión</div></div><div class="stat-icon">◷</div></div></article><article class="card"><div class="stat"><div><div class="stat-label">Límite diario restante</div><div class="stat-value">${money(35000)}</div><div class="stat-note">Se reinicia a medianoche</div></div><div class="stat-icon">⌁</div></div></article></div><div class="grid dashboard-grid"><article class="card"><div class="section-title"><h2>Mis cuentas</h2><a href="#" data-page="accounts">Ver todas</a></div><div class="account-list">${accountsForProfile().map((a) => `<div class="account-row"><div><div class="account-name">${esc(a.name)}</div><div class="account-number">${esc(a.number)} · ${a.currency}</div></div><div class="balance">${money(a.balance,a.currency)}<small>Balance disponible</small></div><div><span class="tag">Activa</span></div><button class="icon-button" aria-label="Más opciones para ${esc(a.name)}" data-action="account-menu">···</button></div>`).join('')}</div></article><article class="card"><div class="section-title"><h2>Actividad reciente</h2><a href="#" data-page="audit">Ver auditoría</a></div><div class="activity-list">${activity('Transferencia entre cuentas','Hoy, 09:42','− RD$2,500.00','negative')}${activity('Pago de servicio · Internet','Ayer, 16:08','− RD$3,200.00','negative')}${activity('Depósito recibido','12 oct, 11:22','+ RD$15,000.00','positive')}</div><details class="details"><summary>Consejos de seguridad</summary><p class="helper">Revisa las aprobaciones pendientes y mantén actualizados los límites por rol.</p></details></article></div>`;
  return shell(content, 'Resumen');
}
