function personalLoanPage() {
  const stage = state.personalStage;
  if (stage >= PERSONAL_LOAN_STAGES.length) return personalLoanReview();
  const section = PERSONAL_LOAN_STAGES[stage];
  const fields = section.fields.map(([label,key,type,choices]) => {
    const value = state.personalAnswers[key] ?? '';
    return type === 'select'
      ? select(label,key,choices,value)
      : input(label,key,value,type,`${type === 'number' ? 'min="0" step="0.01"' : ''} required`);
  }).join('');
  const tableRows = (kind, rows) => rows.map((rowId,index)=>{ const prefix=`loan-${kind}-${rowId}`; const label=kind==='income'?'ingreso':'compromiso'; const typeChoices=kind==='income'?[['Salary','Salario'],['Bonus','Bonificación'],['Other','Otro ingreso']]:[['Housing','Vivienda'],['Loan','Préstamo'],['Card','Tarjeta']]; const typeValue=state.personalAnswers[`${prefix}-type`]||''; const frequencyValue=state.personalAnswers[`${prefix}-frequency`]||''; return `<tr data-testid="${kind}-row"><td><label class="sr-only" for="${prefix}-type">Tipo de ${label} fila ${index+1}</label><select class="control" id="${prefix}-type" name="${prefix}-type" required><option value="" disabled ${typeValue?'':'selected'}>Selecciona un tipo</option>${typeChoices.map(([value,text])=>`<option value="${value}" ${typeValue===value?'selected':''}>${esc(text)}</option>`).join('')}</select></td><td><label class="sr-only" for="${prefix}-amount">${label==='ingreso'?'Importe de ingreso':'Importe de compromiso'} fila ${index+1}</label><input class="control" id="${prefix}-amount" name="${prefix}-amount" type="number" min="0" step="0.01" required data-loan-row-amount="${kind}" value="${esc(state.personalAnswers[`${prefix}-amount`]??'')}"></td><td><label class="sr-only" for="${prefix}-frequency">Frecuencia de ${label} fila ${index+1}</label><select class="control" id="${prefix}-frequency" name="${prefix}-frequency" required><option value="" disabled ${frequencyValue?'':'selected'}>Selecciona una frecuencia</option>${[['Monthly','Mensual'],['Biweekly','Quincenal']].map(([value,text])=>`<option value="${value}" ${frequencyValue===value?'selected':''}>${text}</option>`).join('')}</select></td><td><button class="button ghost" type="button" data-action="remove-${kind}" data-row="${rowId}" aria-label="Eliminar ${label} ${index+1}">Quitar</button></td></tr>`; }).join('');
  const monthlyTable = [3,4].includes(stage) ? `<div class="section-title"><h3>${stage===3?'Detalle de ingresos':'Detalle de compromisos'} en tabla</h3><span class="tag" data-testid="${stage===3?'income':'commitment'}-row-count">${stage===3?state.personalIncomeRows.length:state.personalCommitmentRows.length} filas</span></div><div class="table-wrap"><table><caption class="helper" style="text-align:left;padding:8px">${stage===3?'Desglosa ingresos mensuales':'Desglosa compromisos mensuales'} para la evaluación</caption><thead><tr><th>Concepto</th><th>Importe mensual (RD$)</th><th>Frecuencia</th><th>Acción</th></tr></thead><tbody>${stage===3?tableRows('income',state.personalIncomeRows):tableRows('commitment',state.personalCommitmentRows)}</tbody><tfoot><tr><th colspan="2">Total desglosado</th><td colspan="2"><output data-testid="${stage===3?'income':'commitment'}-table-total">Calculado al revisar</output></td></tr></tfoot></table></div><button class="button secondary" type="button" data-action="add-${stage===3?'income':'commitment'}">Agregar ${stage===3?'ingreso':'compromiso'}</button>` : '';
  return shell(`${pageHead('Solicitud personal · sección '+(stage+1)+' de '+PERSONAL_LOAN_STAGES.length,'Préstamo personal','Completa la solicitud en varias secciones; podrás revisar tus datos antes de enviarla.')}<div class="card" style="max-width:920px"><div class="section-title"><h2>${esc(section.title)}</h2><span class="tag blue">Sección ${stage+1} / ${PERSONAL_LOAN_STAGES.length}</span></div><div class="progress-track" aria-label="Progreso de la solicitud"><div class="progress-fill" style="width:${Math.round((stage+1)/PERSONAL_LOAN_STAGES.length*100)}%"></div></div>${state.alert ? `<div class="alert" role="alert">${esc(state.alert)}</div>` : ''}<form id="personal-loan-form" novalidate><div class="form-grid">${fields}</div>${monthlyTable}<div class="toolbar"><button class="button secondary" type="button" data-action="loan-back" ${stage===0?'disabled':''}>Volver</button><span class="grow"></span><button class="button" type="submit">${stage===PERSONAL_LOAN_STAGES.length-1?'Revisar solicitud':'Avanzar a '+esc(PERSONAL_LOAN_STAGES[stage+1].title)}</button></div></form></div>`,'Préstamo personal');
}
function personalLoanReview() {
  const summary = PERSONAL_LOAN_STAGES.flatMap(section=>section.fields).map(([label,key])=>`<span class="key">${esc(label)}</span><span class="value">${esc(state.personalAnswers[key]||'—')}</span>`).join('');
  return shell(`${pageHead('Solicitud personal','Revisión de solicitud','Confirma la información antes de enviar la solicitud para evaluación.')}<div class="card" style="max-width:920px"><h2>Datos capturados</h2><div class="summary">${summary}</div><div class="toolbar"><button class="button secondary" data-action="loan-back">Editar última sección</button><span class="grow"></span><button class="button" data-action="loan-send-code">Solicitar código de autorización</button></div>${state.otpSent?`<form id="personal-loan-authorize">${input('Código de autorización','loan-authorization-code','','text','inputmode="numeric" autocomplete="one-time-code" maxlength="6"')}<button class="button" type="submit">Enviar solicitud</button></form>`:''}${state.alert ? `<div class="alert" role="alert">${esc(state.alert)}</div>` : ''}</div>`,'Revisar solicitud personal');
}
