function transferContent() {
  const active = (step, label) => `<div class="step ${state.transferStep === step ? 'active' : state.transferStep > step ? 'complete' : ''}"><span class="step-dot">${state.transferStep > step ? '✓' : step}</span>${label}</div>`;
  const header = `${pageHead('Pagos y transferencias','Transferencia entre cuentas propias','Envía fondos entre tus productos con confirmación y autorización de seguridad.') }<div class="steps">${active(1,'Datos')}<span class="step-line"></span>${active(2,'Confirmación')}<span class="step-line"></span>${active(3,'Autorización')}<span class="step-line"></span>${active(4,'Comprobante')}</div>`;
  if (state.transferStep === 1) return `${header}<div class="grid dashboard-grid"><article class="card"><div class="section-title"><h2>Datos de la transferencia</h2><span class="tag blue">Cuentas propias</span></div>${state.alert ? `<div class="alert" role="alert">${esc(state.alert)}</div>` : ''}<form id="transfer-form"><div class="form-grid">${select('Cuenta de origen','source-account',accountsForProfile().map((a)=>[a.id,`${a.name} ${a.number} (${a.currency})`]),'checking-001')}${select('Cuenta de destino','destination-account',accountsForProfile().map((a)=>[a.id,`${a.name} ${a.number} (${a.currency})`]),'savings-002')}${input('Monto','transfer-amount','10','number','min="0" step="0.01" inputmode="decimal"')}${select('Moneda','transfer-currency',[['DOP','Peso dominicano (DOP)'],['USD','Dólar estadounidense (USD)']],'DOP')}</div><div class="info-note">Se mostrará una confirmación con cargos, impuestos y tasa de cambio cuando aplique.</div><button class="button" type="submit">Continuar a la confirmación</button></form></article><aside class="card"><div class="section-title"><h2>Límites de operación</h2></div><div class="summary"><span class="key">Límite por transacción</span><span class="value">RD$50,000.00</span><span class="key">Límite diario restante</span><span class="value">RD$35,000.00</span><span class="key">Comisión estimada</span><span class="value">RD$0.00</span></div><details class="details"><summary>¿Cómo se calcula el total?</summary><p class="helper">El total debitar incluye monto, comisión e impuestos aplicables. Las conversiones usan la tasa vigente que aparece en la confirmación.</p></details></aside></div>`;
  if (state.transferStep === 2) return `${header}<div class="card" style="max-width:820px"><div class="section-title"><h2>Confirma los datos</h2><span class="tag amber">Revisa antes de continuar</span></div><div class="summary"><span class="key">Cuenta de origen</span><span class="value">${esc(state.transfer.sourceLabel)}</span><span class="key">Cuenta de destino</span><span class="value">${esc(state.transfer.destinationLabel)}</span><span class="key">Monto a transferir</span><span class="value">${money(state.transfer.amount,state.transfer.currency)}</span><span class="key">Comisión</span><span class="value">${money(state.transfer.fee,state.transfer.currency)}</span><span class="key">Impuestos</span><span class="value">${money(state.transfer.tax,state.transfer.currency)}</span><span class="key">Tasa de cambio</span><span class="value">${state.transfer.currency === 'USD' ? 'RD$60.50 / US$1.00' : 'No aplica'}</span><span class="key"><strong>Total a debitar</strong></span><span class="value"><strong>${money(state.transfer.total,state.transfer.currency)}</strong></span></div>${state.alert ? `<div class="alert" role="alert">${esc(state.alert)}</div>` : ''}<div class="head-actions" style="justify-content:flex-end;margin-top:18px"><button class="button secondary" data-action="edit-transfer">Editar datos</button><button class="button" data-action="confirm-transfer">Continuar a autorización</button></div></div>`;
  if (state.transferStep === 3) return `${header}<div class="card" style="max-width:700px"><div class="section-title"><h2>Validación de identidad</h2><span class="tag blue">Token de transferencia</span></div><p class="helper">Ingresa el token de seguridad independiente del código usado para iniciar sesión.</p>${state.alert ? `<div class="alert" role="alert">${esc(state.alert)}</div>` : ''}<button class="button secondary" data-action="send-token">Solicitar token por SMS</button><form id="token-form" style="margin-top:18px">${input('Token de seguridad','transfer-token','','text','autocomplete="one-time-code" inputmode="numeric" maxlength="6" aria-describedby="token-help"')}<small id="token-help" class="helper">El token tiene seis dígitos.</small><div class="head-actions" style="margin-top:14px"><button class="button secondary" type="button" data-action="back-confirm">Volver</button><button class="button" type="submit">Autorizar transferencia</button></div></form></div>`;
  return `${header}<div class="card" style="max-width:760px"><div class="receipt-mark" aria-label="Transferencia exitosa">✓</div><h2 style="text-align:center;font:700 16px Manrope;margin:0">Comprobante de transferencia</h2><p style="text-align:center;color:#168365;font-size:12px;font-weight:700">Transacción exitosa</p><div class="receipt-amount">${money(state.transfer.amount,state.transfer.currency)}</div><div class="receipt-ref">${esc(state.transfer.date)} · Referencia ${esc(state.transfer.reference)}</div><div class="summary"><span class="key">Cuenta de origen</span><span class="value">${esc(state.transfer.sourceLabel)}</span><span class="key">Cuenta de destino</span><span class="value">${esc(state.transfer.destinationLabel)}</span><span class="key">Monto</span><span class="value">${money(state.transfer.amount,state.transfer.currency)}</span><span class="key">Total debitado</span><span class="value">${money(state.transfer.total,state.transfer.currency)}</span></div><div class="head-actions" style="justify-content:center;margin-top:20px"><button class="button secondary" data-action="download-receipt">Descargar comprobante</button><button class="button" data-page="dashboard">Volver al resumen</button></div></div>`;
}
