function getStatementRows() {
  return STATEMENT_ROWS.filter((row) =>
    row.account === state.reportAccount && row.date >= state.reportFrom && row.date <= state.reportTo &&
    (state.reportFilter === 'Todas' || row.status === state.reportFilter) &&
    (state.reportMovement === 'all' || row.type === state.reportMovement) && row.amount >= Number(state.reportMinAmount || 0));
}
function statementsPage() {
  const rows = getStatementRows();
  const content = `${pageHead('Consultas','Estados de cuenta','Filtra movimientos por producto, rango de fechas y estado.', '<button class="button secondary" data-action="download-statement">Exportar CSV</button>')}<div class="card"><div class="form-grid three">${select('Cuenta','statement-account',accountsForProfile().map((a)=>[a.id,a.name]),state.reportAccount)}${input('Desde','date-from',state.reportFrom,'date')}${input('Hasta','date-to',state.reportTo,'date')}${select('Estado','statement-status',[['Todas','Todos los estados'],['Completada','Completada'],['Pendiente','Pendiente']],state.reportFilter)}${select('Tipo de movimiento','movement-type',[['all','Todos'],['transfer','Transferencias'],['payment','Pagos'],['deposit','Depósitos']],state.reportMovement)}${input('Monto mínimo','min-amount-input',String(state.reportMinAmount),'number','min="0" max="50000" step="500"')}<div class="field"><label for="min-amount">Deslizador de monto mínimo: <output id="amount-output">RD$${Number(state.reportMinAmount).toLocaleString('es-DO')}</output></label><input id="min-amount" type="range" min="0" max="50000" step="500" value="${esc(state.reportMinAmount)}" aria-label="Deslizador de monto mínimo"></div></div><div class="toolbar"><button class="button" data-action="filter-statements">Aplicar filtros</button><button class="button secondary" data-action="reset-filters">Limpiar filtros</button><span class="grow"></span><span class="tag" data-testid="statement-result-count">${rows.length} resultados</span></div><div class="table-wrap"><table><caption class="helper" style="text-align:left;padding:8px">Movimientos de la cuenta seleccionada</caption><thead><tr><th>Fecha</th><th>Descripción</th><th>Referencia</th><th>Monto</th><th>Estado</th></tr></thead><tbody>${rows.map(r=>`<tr>${[r.dateLabel,r.description,r.reference,r.amountLabel,r.status].map((cell,i)=>`<td>${i===1?`<a class="table-link" href="#" data-action="movement-detail">${esc(cell)}</a>`:esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pagination"><span>${rows.length ? `1–${rows.length}` : '0'} de ${rows.length} movimientos</span><span>Actualizado hace unos segundos</span></div></div>`;
  return shell(content,'Estados de cuenta');
}
