function auditPage() {
  const cutoff=new Date('2026-10-16T00:00:00');cutoff.setDate(cutoff.getDate()-Number(state.auditPeriod));
  const q=state.auditSearch.toLowerCase();const rows=AUDIT_EVENTS.filter(e=>new Date(e.date+'T00:00:00')>=cutoff&&`${e.user} ${e.event} ${e.reference}`.toLowerCase().includes(q));
  return shell(`${pageHead('Seguridad','Registro de auditoría','Historial de accesos, cambios de permisos y transacciones.')}<div class="toolbar"><div class="grow"><input class="control" aria-label="Buscar en auditoría" placeholder="Buscar por usuario, evento o referencia" value="${esc(state.auditSearch)}" data-input="audit-filter"></div>${select('Periodo','audit-period',[['7','Últimos 7 días'],['30','Últimos 30 días'],['90','Últimos 90 días']],state.auditPeriod)}<button class="button secondary" data-action="download-audit">Exportar registro</button></div><div class="card"><div class="section-title"><h2>Eventos auditados</h2><span class="tag" data-testid="audit-count">${rows.length} eventos</span></div><div class="table-wrap"><table><caption class="helper" style="text-align:left;padding:8px">Registro de auditoría empresarial</caption><thead><tr><th>Usuario</th><th>Fecha y hora</th><th>Evento</th><th>Resultado</th><th>Referencia</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.user)}</td><td>${esc(row.time)}</td><td>${esc(row.event)}</td><td><span class="tag">${esc(row.result)}</span></td><td>${esc(row.reference)}</td></tr>`).join('')}</tbody></table></div></div>`,'Auditoría');
}
function loginPage() {
  const personal = state.profile === 'Personal';
  const content = state.page === 'otp' ? `<div class="login-shell"><section class="login-card"><div class="login-brand"><div class="brand-mark">N</div><strong>Northstar</strong></div><h1>Verificación de acceso</h1><p>Confirma tu identidad para continuar al portal ${personal?'personal':'empresarial'}.</p>${state.alert ? `<div class="alert" role="alert">${esc(state.alert)}</div>` : ''}${state.otpSent ? `<div class="success-note" role="status">Código de prueba enviado por SMS al teléfono registrado.</div>` : ''}<button class="button secondary" type="button" data-action="send-login-otp">Solicitar código por SMS</button><form id="otp-form">${input('Código de acceso','login-otp','','text','inputmode="numeric" autocomplete="one-time-code" maxlength="6" required')}<button class="button" type="submit">Continuar</button></form><div class="login-footer">El código de acceso es independiente del token de transferencia.</div></section></div>` : `<div class="login-shell"><section class="login-card"><div class="login-brand"><div class="brand-mark">N</div><div><strong>Northstar</strong><div class="helper">Portal ${personal?'personal':'empresarial'} seguro</div></div></div><div class="eyebrow">Entorno de pruebas · Datos ficticios</div><h1>Iniciar sesión</h1><p>Accede a tus productos y operaciones ${personal?'personales':'empresariales'}.</p><div class="profile-switch"><button class="${personal?'':'active'}" type="button" data-action="enterprise-profile">Empresarial</button><button class="${personal?'active':''}" type="button" data-action="personal-profile">Personal</button></div>${state.alert ? `<div class="alert" role="alert">${esc(state.alert)}</div>` : ''}<form id="login-form">${personal?input('Cédula','login-identity','','text','inputmode="numeric" autocomplete="username" required'):input('RNC','login-rnc','','text','inputmode="numeric" autocomplete="username" required')}${input('Usuario','login-user','','text','autocomplete="username" required')}${input('Contraseña','login-password','','password','autocomplete="current-password" required')}<button class="button" type="submit">Iniciar sesión</button></form><div class="login-footer">Acceso protegido · Espacio de regresión local</div></section></div>`;
  return state.loading ? `<main aria-busy="true" aria-live="polite">${spinner(state.page === 'login' ? 'Validando credenciales…' : 'Verificando el código de acceso…')}</main>` : content;
}
function render() {
  if (state.page === 'login' || state.page === 'otp') { root.innerHTML = loginPage(); bind(); return; }
  let html = '';
  switch (state.page) {
    case 'dashboard': html = dashboard(); break;
    case 'personal-loan': html = personalLoanPage(); break;
    case 'personal-loan-success': html = personalLoanSuccess(); break;
    case 'accounts': html = accountsPage(); break;
    case 'transfer': html = shell(transferContent(),'Transferencias'); break;
    case 'beneficiaries': html = beneficiariesPage(); break;
    case 'payments': html = state.paymentStep === 2 ? paymentReview() : paymentsPage(); break;
    case 'statements': html = statementsPage(); break;
    case 'payroll': html = payrollPage(); break;
    case 'admin': html = adminPage(); break;
    case 'audit': html = auditPage(); break;
    default: html = state.authenticated ? dashboard() : loginPage();
  }
  root.innerHTML = html; bind();
}
function bind() {
  root.querySelectorAll('[data-page]').forEach((button) => button.addEventListener('click', (event) => { event.preventDefault(); const page = button.getAttribute('data-page'); if (page === 'transfer') { state.transferStep = 1; state.transfer = null; } if (page === 'personal-loan' && state.page === 'personal-loan-success') { state.personalStage=0; state.personalAnswers={}; state.otpSent=false; } setPage(page); }));
  root.querySelectorAll('[data-action]').forEach((button) => button.addEventListener('click', (event) => { event.preventDefault(); action(button.dataset.action,button); }));
  root.querySelectorAll('[data-input="beneficiary-filter"]').forEach((el) => el.addEventListener('input', () => { state.filterText = el.value; const pos = el.selectionStart; render(); const next = root.querySelector('[data-input="beneficiary-filter"]'); next?.focus(); next?.setSelectionRange(pos,pos); }));
  root.querySelectorAll('[data-input="audit-filter"]').forEach((el) => el.addEventListener('input', () => { state.auditSearch=el.value;const pos=el.selectionStart;render();const next=root.querySelector('[data-input="audit-filter"]');next?.focus();next?.setSelectionRange(pos,pos); }));
  root.querySelector('#loan-province')?.addEventListener('change',(event)=>{const municipality=root.querySelector('#loan-city');if(!municipality)return;const options=MUNICIPALITIES_BY_PROVINCE[event.currentTarget.value]||ALL_MUNICIPALITIES;const current=municipality.value;municipality.innerHTML=options.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join('');municipality.value=options.some(([value])=>value===current)?current:(options[0]?.[0]||'');});
  root.querySelectorAll('[data-payroll-field]').forEach((el) => el.addEventListener('input', () => { const row=state.payrollRows.find(item=>item.id===Number(el.dataset.rowId)); if(row)row[el.dataset.payrollField]=el.value; const output=root.querySelector('[data-testid="payroll-total"]'); if(output)output.textContent=money(state.payrollRows.reduce((sum,item)=>sum+Number(item.amount||0),0)); }));
  const updateLoanRowTotal = (kind) => { const output=root.querySelector(`[data-testid="${kind}-table-total"]`); if(output)output.textContent=money([...root.querySelectorAll(`[data-loan-row-amount="${kind}"]`)].reduce((sum,field)=>sum+Number(field.value||0),0)); };
  root.querySelectorAll('[data-loan-row-amount]').forEach((el) => { const kind=el.dataset.loanRowAmount; el.addEventListener('input',()=>updateLoanRowTotal(kind)); });
  for (const kind of ['income','commitment']) updateLoanRowTotal(kind);
  root.querySelector('#audit-period')?.addEventListener('change', (event) => { state.auditPeriod=event.currentTarget.value;render(); });
  const amountRange = root.querySelector('#min-amount'); const amountNumber=root.querySelector('#min-amount-input');
  amountRange?.addEventListener('input', () => { if(amountNumber)amountNumber.value=amountRange.value; root.querySelector('#amount-output').textContent = `RD$${Number(amountRange.value).toLocaleString('es-DO')}`; });
  amountNumber?.addEventListener('input', () => { if(amountRange)amountRange.value=amountNumber.value; root.querySelector('#amount-output').textContent = `RD$${Number(amountNumber.value||0).toLocaleString('es-DO')}`; });
  const limitRange = root.querySelector('#approval-limit-slider'); const limitNumber=root.querySelector('#approval-limit');
  limitRange?.addEventListener('input', () => { if(limitNumber)limitNumber.value=limitRange.value; root.querySelector('#limit-output').textContent = `RD$${Number(limitRange.value).toLocaleString('es-DO')}`; });
  limitNumber?.addEventListener('input', () => { if(limitRange)limitRange.value=limitNumber.value; root.querySelector('#limit-output').textContent = `RD$${Number(limitNumber.value||0).toLocaleString('es-DO')}`; });
  root.querySelector('#login-form')?.addEventListener('submit', (event) => { event.preventDefault(); const data = new FormData(event.currentTarget); state.alert = ''; const personal = state.profile === 'Personal'; const valid = personal ? data.get('login-identity') === DEMO.personal.identity && data.get('login-user') === DEMO.personal.user && data.get('login-password') === DEMO.personal.password : data.get('login-rnc') === DEMO.rnc && data.get('login-user') === DEMO.user && data.get('login-password') === DEMO.password; if (!valid) { state.alert = personal ? 'Cédula, usuario o contraseña no válidos.' : 'RNC, usuario o contraseña no válidos.'; render(); return; } state.loading = true; state.page = 'login'; render(); setTimeout(() => { state.loading = false; state.page = 'otp'; state.otpSent = false; render(); }, 520); });
  root.querySelector('#otp-form')?.addEventListener('submit', (event) => { event.preventDefault(); const value = new FormData(event.currentTarget).get('login-otp'); const expected = state.profile === 'Personal' ? DEMO.personal.otp : DEMO.otp; if (value !== expected) { state.alert = 'El código de acceso no es válido.'; render(); return; } state.authenticated = true; state.alert = ''; setPage('dashboard'); });
   root.querySelector('#personal-loan-form')?.addEventListener('submit', (event) => { event.preventDefault(); const form=event.currentTarget; const values = Object.fromEntries(new FormData(form).entries()); state.personalAnswers = {...state.personalAnswers,...values}; const invalidControl=Array.from(form.elements).find(control=>control.required&&!control.validity.valid); if(invalidControl){const label=invalidControl.labels?.[0]?.textContent?.trim()||invalidControl.getAttribute('aria-label')||invalidControl.name||'campo requerido';state.alert=`Campo incompleto: ${label}.`;render();return;} state.alert = ''; state.loading=true; render(); const nextStage=state.personalStage+1; setTimeout(()=>{state.personalStage=nextStage;state.loading=false;render();},420); });
  root.querySelector('#personal-loan-authorize')?.addEventListener('submit', (event) => { event.preventDefault(); const code = new FormData(event.currentTarget).get('loan-authorization-code'); if (code !== DEMO.personal.otp) { state.alert='El código de autorización no es válido.'; render(); return; } state.alert=''; state.otpSent=false; setPage('personal-loan-success'); });
  root.querySelector('#transfer-form')?.addEventListener('submit', (event) => { event.preventDefault(); const data = new FormData(event.currentTarget); const source = accountsForProfile().find((a)=>a.id===data.get('source-account')); const dest = accountsForProfile().find((a)=>a.id===data.get('destination-account')); const amount = Number(data.get('transfer-amount')); const currency = data.get('transfer-currency'); if (!source || !dest) return; if (source.id === dest.id) { state.alert = 'La cuenta de origen y destino deben ser diferentes.'; render(); return; } if (!(amount > 0)) { state.alert = 'Ingresa un monto mayor que cero.'; render(); return; } if (amount > source.balance) { state.alert = 'El monto supera el balance disponible de la cuenta de origen.'; render(); return; } state.transfer = { sourceId:source.id,destinationId:dest.id,sourceLabel:`${source.name} ${source.number}`,destinationLabel:`${dest.name} ${dest.number}`,amount,currency,fee:0,tax:0,total:amount,date:new Date().toLocaleString('es-DO'),reference:`LAB-${Date.now().toString().slice(-8)}` }; state.transferStep=2; setPage('transfer'); });
  root.querySelector('#token-form')?.addEventListener('submit', (event) => { event.preventDefault(); const token = new FormData(event.currentTarget).get('transfer-token'); if (token !== DEMO.token) { state.alert = 'El token de seguridad no es válido. La transferencia no se ejecutó.'; render(); return; } state.transferStep=4; state.transfer.reference=`LAB-${Date.now().toString().slice(-8)}`; state.transfer.date=new Date().toLocaleString('es-DO'); setPage('transfer'); });
  root.querySelector('#beneficiary-form')?.addEventListener('submit', (event) => { event.preventDefault(); const d = new FormData(event.currentTarget); const acct = String(d.get('beneficiary-account')||'').trim(); if (!d.get('beneficiary-name')||!acct) { state.alert='Completa el nombre y el número de cuenta.'; render(); return; } if (DEMO.beneficiaries.some((b)=>b.account.endsWith(acct.slice(-4))||b.alias.toLowerCase()===String(d.get('beneficiary-alias')).toLowerCase())) { state.alert='Ya existe un beneficiario con esa cuenta o alias.'; render(); return; } const chosen=[...event.currentTarget.querySelectorAll('input[type=checkbox]:checked')].map((x)=>x.parentElement.textContent.trim()); state.selectedChannels=chosen; DEMO.beneficiaries.push({name:String(d.get('beneficiary-name')),account:`•••• ${acct.slice(-4)}`,bank:String(d.get('beneficiary-bank')),alias:String(d.get('beneficiary-alias')||d.get('beneficiary-name'))}); state.beneficiaryDialog=false; state.alert=''; render(); toast('Beneficiario agregado correctamente.'); });
  root.querySelector('#payment-form')?.addEventListener('submit', (event) => { event.preventDefault(); const d=new FormData(event.currentTarget); const amount=Number(d.get('payment-amount')); const date=String(d.get('payment-date')||''); const provider=PAYMENT_PROVIDERS.find(([value])=>value===d.get('provider')); const frequency=PAYMENT_FREQUENCIES.find(([value])=>value===d.get('payment-frequency')); if (!(amount>0)) {state.alert='El monto debe ser mayor que cero.';render();return;} if (date < new Date().toISOString().slice(0,10)) {state.alert='La fecha de pago no puede estar en el pasado.';render();return;} const account=accountsForProfile().find(a=>a.id===d.get('payment-account')); state.paymentChannels=d.getAll('payment-channel').map(String); state.payment={provider:d.get('provider'),providerLabel:provider?.[1]||d.get('provider'),contract:d.get('contract-number'),accountId:d.get('payment-account'),account:account?.name||'',amount,date,frequency:d.get('payment-frequency'),frequencyLabel:frequency?.[1]||d.get('payment-frequency')}; state.alert=''; state.paymentStep=2; setPage('payments'); });
  root.querySelector('#role-form')?.addEventListener('submit',(event)=>{event.preventDefault();const data=new FormData(event.currentTarget);state.userRole=String(data.get('user-role'));state.approvalLimit=Number(data.get('approval-limit'));state.rolePermissions=data.getAll('permission').map(String);state.alert='';render();toast('La política de aprobación se guardó.');});
  root.querySelector('#payroll-form')?.addEventListener('submit',(event)=>{event.preventDefault();const data=new FormData(event.currentTarget);const source=accountsForProfile().find(account=>account.id===data.get('payroll-source'));const rows=state.payrollRows.map(row=>({...row,amount:Number(row.amount)}));const seen=new Set();for(const [index,row] of rows.entries()){if(!row.name.trim()||!row.concept.trim()||!/^\d{8,}$/.test(row.account)){state.alert=`Completa destinatario, cuenta (mínimo 8 dígitos) y concepto en la fila ${index+1}.`;render();return;}if(!(row.amount>0)){state.alert=`El monto de la fila ${index+1} debe ser mayor que cero.`;render();return;}if(seen.has(row.account)){state.alert=`La cuenta receptora de la fila ${index+1} está duplicada.`;render();return;}seen.add(row.account);}const date=String(data.get('payroll-date')||'');if(date<new Date().toISOString().slice(0,10)){state.alert='La fecha de aplicación no puede estar en el pasado.';render();return;}const total=rows.reduce((sum,row)=>sum+row.amount,0);if(!source||total>source.balance){state.alert='El total del lote supera el balance disponible de la cuenta a debitar.';render();return;}state.payrollBatch={sourceId:source.id,sourceLabel:`${source.name} ${source.number}`,date,concept:String(data.get('payroll-batch-concept')||''),rows};state.alert='';state.payrollStep=2;setPage('payroll');});
  root.querySelector('#payroll-token-form')?.addEventListener('submit',(event)=>{event.preventDefault();const token=new FormData(event.currentTarget).get('payroll-token');if(token!==DEMO.token){state.alert='El token no es válido. El lote no fue procesado.';render();return;}state.alert='';state.otpSent=false;state.payrollStep=4;state.payrollBatch.reference=`BATCH-${Date.now().toString().slice(-8)}`;setPage('payroll');});
}
function action(name, element) {
  if (name === 'personal-profile' || name === 'enterprise-profile') { state.profile=name === 'personal-profile'?'Personal':'Empresarial'; state.alert=''; state.page='login'; render(); return; }
  if (name === 'add-income' || name === 'add-commitment') { const form=root.querySelector('#personal-loan-form'); if(form)state.personalAnswers={...state.personalAnswers,...Object.fromEntries(new FormData(form).entries())}; const rows=name==='add-income'?state.personalIncomeRows:state.personalCommitmentRows; rows.push(Math.max(0,...rows)+1); render(); toast(name==='add-income'?'Se agregó una fila de ingreso.':'Se agregó una fila de compromiso.'); return; }
  if (name === 'payroll-add-row') { state.payrollRows.push({id:state.payrollNextRowId++,name:'',account:'',amount:'',concept:''});render();return; }
  if (name === 'payroll-remove-row') { if(state.payrollRows.length>1)state.payrollRows=state.payrollRows.filter(row=>row.id!==Number(element?.dataset.row));render();return; }
  if (name === 'payroll-edit' || name === 'payroll-review') { state.alert='';state.payrollStep=name==='payroll-edit'?1:2;setPage('payroll');return; }
  if (name === 'payroll-authorize') { state.alert='';state.otpSent=false;state.payrollStep=3;setPage('payroll');return; }
  if (name === 'payroll-new') { state.payrollStep=1;state.payrollBatch=null;state.payrollRows=[{id:state.payrollNextRowId++,name:'',account:'',amount:'',concept:''}];state.alert='';setPage('payroll');return; }
  if (name === 'remove-income' || name === 'remove-commitment') { const form=root.querySelector('#personal-loan-form'); if(form)state.personalAnswers={...state.personalAnswers,...Object.fromEntries(new FormData(form).entries())}; const rows=name==='remove-income'?state.personalIncomeRows:state.personalCommitmentRows; if(rows.length>1){rows.splice(rows.indexOf(Number(element?.dataset.row)),1);render();} return; }
  if (name === 'loan-back') { state.alert=''; state.personalStage=Math.max(0,Math.min(PERSONAL_LOAN_STAGES.length-1,state.personalStage-1)); state.otpSent=false; render(); return; }
  if (name === 'loan-send-code') { state.alert=''; state.otpSent=true; render(); toast('Código de autorización enviado para la prueba.'); return; }
  if (name === 'send-login-otp') { state.otpSent = true; render(); return; }
  if (name === 'send-token') { state.alert=''; render(); toast('Token de prueba enviado por SMS.'); return; }
  if (name === 'edit-transfer') { state.transferStep=1; render(); return; }
  if (name === 'confirm-transfer') { state.alert=''; state.transferStep=3; setPage('transfer'); return; }
  if (name === 'back-confirm') { state.transferStep=2; state.alert=''; render(); return; }
  if (name === 'confirm-payment') { state.paymentStep=1; setPage('dashboard'); toast('Pago de prueba completado correctamente.'); return; }
  if (name === 'edit-payment') { state.alert=''; state.paymentStep=1; setPage('payments'); return; }
  if (name === 'add-beneficiary') { state.alert=''; state.beneficiaryDialog=true; render(); root.querySelector('#beneficiary-name')?.focus(); return; }
  if (name === 'close-beneficiary') { state.beneficiaryDialog=false; state.alert=''; render(); return; }
  if (name === 'notifications') { state.notifications=!state.notifications; render(); return; }
  if (name === 'user-menu') { state.authenticated=false; state.otpSent=false; state.page='login'; render(); return; }
  if (name === 'refresh-accounts' || name === 'refresh-beneficiaries') { state.loading=true; render(); setTimeout(()=>{state.loading=false;render();toast('Los datos se actualizaron.');},650); return; }
  if (name === 'filter-statements') { state.reportAccount=root.querySelector('#statement-account')?.value||'checking-001'; state.reportFrom=root.querySelector('#date-from')?.value||'2026-10-01'; state.reportTo=root.querySelector('#date-to')?.value||'2026-10-16'; state.reportFilter=root.querySelector('#statement-status')?.value||'Todas'; state.reportMovement=root.querySelector('#movement-type')?.value||'all'; state.reportMinAmount=Number(root.querySelector('#min-amount-input')?.value||0); const revision = ++viewRevision; state.loading=true; render(); setTimeout(()=>{ if (revision !== viewRevision || state.page !== 'statements') return; state.loading=false; render(); },380); return; }
  if (name === 'reset-filters') { state.reportFilter='Todas'; state.reportMovement='all'; state.reportAccount='checking-001'; state.reportFrom='2026-10-01'; state.reportTo='2026-10-16'; state.reportMinAmount=0; render(); return; }
  if (name === 'download-statement') { const rows=getStatementRows(); const filename='estado-de-cuenta-regression-lab.csv'; const csv=['Fecha,Descripción,Referencia,Monto,Estado',...rows.map(r=>[r.dateLabel,r.description,r.reference,r.amountLabel,r.status].map(v=>`"${String(v).replaceAll('"','""')}"`).join(','))].join('\n'); const link=document.createElement('a'); link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})); link.download=filename; link.click(); setTimeout(()=>URL.revokeObjectURL(link.href),1000); toast(`${rows.length} movimientos exportados en CSV: ${filename}.`); return; }
  if (name === 'download-statement' || name === 'download-audit' || name === 'download-receipt') { toast('El archivo de prueba está listo para descargar.'); return; }
  if (name === 'invite-user') { toast('Invitación de prueba preparada.'); return; }
  if (name === 'account-menu' || name === 'beneficiary-options' || name === 'movement-detail' || name === 'search') { toast('Esta acción está disponible en el entorno de regresión.'); }
}
render();
